$manageUrl=$path.'?tab=performance&id='.$f['performance'];$manage=$request('Admin',$manageUrl);$ok($nodes($manage['body'],'//input[@name="starts" and @type="datetime-local"]')===1&&$nodes($manage['body'],'//select[@name="offset"]')===0,'Future performance without orders has a normal date input and no occurrence selector');
